WITH filtered AS (SELECT *, CAST(is_flagged AS INT) AS is_flagged_flag FROM transactions WHERE txn_time >= '2025-03-01' AND txn_time >= TIMESTAMP '2023-08-03 02:00:00'), flagged AS (SELECT *, CASE WHEN LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) IS NULL OR txn_time > LAG(txn_time) OVER (PARTITION BY txn_type ORDER BY txn_time, id) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM filtered), sessions_transactions AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY txn_type ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT account_id, SUM(CASE WHEN merchant = 'Starbucks' THEN session_start_flag ELSE 0 END) AS starbucks_session_start_flag, COUNT(*) FILTER (WHERE merchant = 'Lazada') AS lazada_rows, AVG(session_start_flag) FILTER (WHERE txn_type = 'DEBIT') AS debit_avg_session_start_flag, MAX(amount) FILTER (WHERE txn_type = 'CREDIT') AS credit_max_amount, COUNT(DISTINCT txn_type) AS distinct_txn_types FROM sessions_transactions GROUP BY account_id HAVING COUNT(DISTINCT txn_type) < 1000
